<?php
/** Admin view of unresolved dependencies for one game. */
declare(strict_types=1);
require_once __DIR__.'/lib/CatalogSupport.php';require_once __DIR__.'/lib/BaseGameProtection.php';require_once __DIR__.'/lib/CatalogDependencyDiagnostics.php';use UnrealDb\Catalog\Infrastructure\Persistence\PdoGameMissingDependencyQuery;catalog_start_session();
function game_missing_int(string $key,int $default=0):int{$v=filter_input(INPUT_GET,$key,FILTER_VALIDATE_INT);return$v===false||$v===null?$default:max(0,(int)$v);}function game_missing_type():string{$v=strtolower(trim((string)($_GET['dependency_type']??'all')));return$v==='base_game'?'base_game':'all';}function game_missing_url(int $gameId,string $type,array $params=[]):string{$q=array_merge(['game_id'=>$gameId,'dependency_type'=>$type],$params);$q=array_filter($q,static fn(mixed $v):bool=>$v!==null&&$v!==''&&$v!==0);return'game-missing.php?'.http_build_query($q);}function game_missing_import_class(string $p,string $n):string{return implode('.',array_values(array_filter([$p,$n],static fn(string $v):bool=>trim($v)!=='')));}function gm_match(bool $v):string{return$v?'<strong>✓ MATCH</strong>':'<strong>✗ DIFFERENT</strong>';}
try{$config=catalog_config();$db=catalog_db($config);if(!catalog_require_admin_page('Game Missing Dependencies'))exit;base_game_ensure($db);$games=catalog_all($db,'SELECT id,name,slug FROM ue_games ORDER BY name');$gameId=game_missing_int('game_id');$game=$gameId>0?catalog_one($db,'SELECT id,name,slug FROM ue_games WHERE id=?',[$gameId]):null;if(!$game)throw new RuntimeException('Choose a valid game from the Games page.');$type=game_missing_type();$baseGameOnly=$type==='base_game';$selectedPackage=substr(trim((string)($_GET['package']??'')),0,255);if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$q=new PdoGameMissingDependencyQuery($db);$scope=$baseGameOnly?$q->officialBaseGamePackageNames($gameId):null;$totals=$q->totals($gameId,$scope);$missingObjects=(int)$totals['missing_objects'];$missingPackages=(int)$totals['missing_packages'];$filesWithMissing=(int)$totals['files_with_missing'];$rows=$selectedPackage!==''?$q->detailRows($gameId,$selectedPackage,$scope,500,0):$q->missingRows($gameId,$scope,500,0);$packageRows=$q->packageRows($gameId,$scope,500,0);
foreach($rows as &$row){$path=(string)($row['required_object_path']??'');$parts=explode('.',$path);$row['import_object_name']=(string)(end($parts)?:'');$row['import_class_package']=(string)($row['class_package']??'');$row['import_class_name']=(string)($row['class_name']??'');$row['provider_candidates']=catalog_dependency_provider_candidates($db,$gameId,(int)$row['file_id'],(string)$row['required_package']);foreach($row['provider_candidates'] as &$provider){$provider['candidate_rows']=catalog_dependency_export_candidates($db,$row,(int)$provider['file_id']);foreach($provider['candidate_rows'] as &$candidate)$candidate['outer_path']=catalog_dependency_export_outer_path($db,(int)$provider['file_id'],(int)$candidate['outer_index'],(string)$row['required_package']);unset($candidate);}unset($provider);}unset($row);
$typeLabel=$baseGameOnly?'Official base-game dependencies only':'All missing dependencies';catalog_head('Missing Dependencies — '.(string)$game['name']);echo <<<'CSS'
<style>.game-missing-filter{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.game-missing-filter label{display:grid;gap:5px}.missing-summary{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:16px 0}.missing-live-filter{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 12px}.missing-live-filter input{width:min(520px,100%);min-width:240px}.missing-package-summary{display:flex;gap:8px;flex-wrap:wrap}.missing-package-pill{display:inline-flex;gap:7px;align-items:center;padding:7px 10px;border:1px solid var(--border,#2b3950);border-radius:8px}.missing-package-extra{display:none}.missing-package-summary.is-expanded .missing-package-extra,.missing-package-summary.is-filtering .missing-package-extra{display:inline-flex}.missing-package-pill.is-filtered,.missing-detail.is-filtered{display:none!important}.missing-detail{border:1px solid var(--border,#2b3950);border-radius:10px;margin:0 0 12px;overflow:hidden}.missing-detail__title{padding:10px 14px;background:rgba(255,255,255,.035);display:flex;gap:12px}.missing-detail__grid{display:grid;grid-template-columns:minmax(190px,.75fr) minmax(260px,1fr) minmax(440px,2fr)}.missing-detail__cell{padding:12px 14px;min-width:0;overflow-wrap:anywhere}.missing-detail__cell+.missing-detail__cell{border-left:1px solid var(--border,#2b3950)}.missing-label{display:block;font-size:.82em;font-weight:700;margin-bottom:6px}.provider-block+.provider-block{margin-top:12px;padding-top:12px;border-top:1px solid var(--border,#2b3950)}.candidate{margin-top:8px;padding:10px;border:1px solid var(--border,#2b3950);border-radius:7px}.compare{width:100%;border-collapse:collapse;margin-top:8px}.compare th,.compare td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--border,#2b3950);vertical-align:top}.compare th{font-size:.82em}.compare td:first-child{font-weight:700;white-space:nowrap}.compare .result{white-space:nowrap}.mismatch-reason{margin-top:8px;font-weight:700}.missing-no-matches{display:none}.missing-no-matches.is-visible{display:block}@media(max-width:900px){.missing-summary,.missing-detail__grid{grid-template-columns:1fr}.missing-detail__cell+.missing-detail__cell{border-left:0;border-top:1px solid var(--border,#2b3950)}.compare{font-size:.9em}}</style>
CSS;
echo CatalogUi::pageHeader('Missing Dependencies — '.(string)$game['name'],$typeLabel.'. Package availability and object resolution are separate checks.',['Games'=>'games.php','Global Missing Files'=>'missing.php','Game Files'=>'game-files.php?id='.$gameId]);echo '<section class="ui-section"><div class="ui-section__body"><form class="game-missing-filter" method="get"><label>Game<select name="game_id">';foreach($games as $g)echo'<option value="'.(int)$g['id'].'"'.((int)$g['id']===$gameId?' selected':'').'>'.catalog_h((string)$g['name']).'</option>';echo'</select></label><label>Dependency type<select name="dependency_type"><option value="all"'.(!$baseGameOnly?' selected':'').'>All missing dependencies</option><option value="base_game"'.($baseGameOnly?' selected':'').'>Official base-game dependencies only</option></select></label><button type="submit">Apply filters</button></form></div></section><div class="missing-summary">';catalog_stat_card('Missing objects',$missingObjects,'Requested object identities that did not resolve',$missingObjects?'attention':'good');catalog_stat_card('Required packages',$missingPackages,'Logical packages referenced by those imports',$missingPackages?'attention':'good');catalog_stat_card('Affected files',$filesWithMissing,'Files containing unresolved imports',$filesWithMissing?'attention':'good');echo'</div>';
if($packageRows!==[]){echo'<section class="ui-section"><div class="ui-section__header"><div><h2>At a glance</h2><p>Unresolved objects grouped by required package. This does not mean the package itself is absent.</p></div></div><div class="ui-section__body"><div class="missing-package-summary">';foreach($packageRows as $p){$name=(string)$p['required_package'];echo'<a class="missing-package-pill" href="'.catalog_h(game_missing_url($gameId,$type,['package'=>$name])).'"><span class="mono">'.catalog_h($name).'</span><strong>'.(int)$p['missing_object_rows'].'</strong><span class="muted small">objects / '.(int)$p['requiring_file_count'].' files</span></a>';}echo'</div></div></section>';}
$title=$selectedPackage!==''?'Unresolved objects requiring '.$selectedPackage:'Unresolved object identities';echo'<section class="ui-section"><div class="ui-section__header"><div><h2>'.catalog_h($title).'</h2><p>The comparison table shows the actual value requested by the importing file beside the value present in each candidate export.</p></div>';if($selectedPackage!=='')echo'<a class="button secondary" href="'.catalog_h(game_missing_url($gameId,$type)).'">Show all</a>';echo'</div><div class="ui-section__body">';if($rows===[])echo CatalogUi::emptyState('No unresolved dependency objects','Nothing currently matches the selected scope.');else foreach($rows as $r){$pkg=(string)$r['required_package'];$class=game_missing_import_class((string)$r['class_package'],(string)$r['class_name']);$providers=(array)($r['provider_candidates']??[]);echo'<article class="missing-detail"><div class="missing-detail__title"><strong><a href="file-info.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_package_name']).'</a></strong><a class="muted" href="file-examine.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_original_name']).'</a></div><div class="missing-detail__grid"><div class="missing-detail__cell"><span class="missing-label">1. FILE REQUESTS</span><div class="mono">'.catalog_h((string)$r['required_object_path']).'</div><div>Class: <span class="mono">'.catalog_h($class!==''?$class:'(not recorded)').'</span></div><div>Package: <strong>'.catalog_h($pkg).'</strong></div></div><div class="missing-detail__cell"><span class="missing-label">2. AVAILABLE PACKAGE FILES</span>';
if($providers===[])echo'<div class="mismatch-reason">No verified physical file providing '.catalog_h($pkg).' exists.</div>';else foreach($providers as $provider)echo'<div class="provider-block"><a href="file-info.php?id='.(int)$provider['file_id'].'"><strong>'.catalog_h((string)$provider['original_name']).'</strong></a><div class="muted small">File #'.(int)$provider['file_id'].' · '.catalog_h((string)$provider['source_kind']).' provider</div></div>';echo'</div><div class="missing-detail__cell"><span class="missing-label">3. VERIFYIMPORT VALUE COMPARISON</span>';
if($providers===[])echo'<div>No candidate export can be checked.</div>';else foreach($providers as $provider){$candidates=(array)($provider['candidate_rows']??[]);echo'<div class="provider-block"><strong>'.catalog_h((string)$provider['original_name']).'</strong>';if($candidates===[]){echo'<div class="mismatch-reason">Requested object name: <span class="mono">'.catalog_h((string)$r['import_object_name']).'</span><br>Provider value: no export with that object name.</div>';continue;}foreach($candidates as $candidate){$s=catalog_dependency_candidate_summary($r,$candidate,(string)($candidate['outer_path']??''));$public=(bool)$s['public'];$all=(bool)$s['object_match']&&(bool)$s['class_package_match']&&(bool)$s['class_name_match']&&(bool)$s['outer_match']&&$public;echo'<div class="candidate"><div><strong>Export #'.(int)$candidate['export_index'].'</strong></div><table class="compare"><thead><tr><th>VerifyImport field</th><th>Requested by importing file</th><th>Value in candidate export</th><th>Comparison</th></tr></thead><tbody>';
foreach([['ObjectName',$s['wanted_object'],$s['actual_object'],$s['object_match']],['ClassPackage',$s['wanted_class_package'],$s['actual_class_package'],$s['class_package_match']],['ClassName',$s['wanted_class_name'],$s['actual_class_name'],$s['class_name_match']],['Outer / parent path',$s['wanted_outer_path'],$s['actual_outer_path'],$s['outer_match']]] as $c)echo'<tr><td>'.catalog_h((string)$c[0]).'</td><td class="mono">'.catalog_h((string)$c[1]).'</td><td class="mono">'.catalog_h((string)$c[2]).'</td><td class="result">'.gm_match((bool)$c[3]).'</td></tr>';echo'<tr><td>RF_Public</td><td>required for this standard VerifyImport check</td><td>'.($public?'yes':'no').' · '.catalog_h((string)$s['flags_hex']).'</td><td class="result">'.gm_match($public).'</td></tr></tbody></table><div class="muted small">Serialized candidate outer index: '.(int)$s['actual_outer_index'].'</div><div class="mismatch-reason">Result: '.($all?'All displayed values match. This row should not be described as an outer mismatch; investigate the resolver/projection state.':'Rejected because the field'.(count(array_filter([$s['object_match'],$s['class_package_match'],$s['class_name_match'],$s['outer_match'],$public],static fn($v)=>!$v))===1?'':'s').' marked DIFFERENT do not satisfy VerifyImport.').'</div></div>';}}echo'</div></div></article>';}echo'</div></section>';catalog_foot();}catch(Throwable $error){if(!headers_sent())catalog_head('Game missing dependencies error');echo CatalogUi::alert('danger',$error->getMessage(),'The filtered missing-dependency page could not be loaded.');catalog_foot();}
